// An invented server library. Its reply object carries sends and a `locals`
// member the server's own code fills; `Ctx` is one object holding both a send
// and the body.
export interface Reply<L = Record<string, unknown>> {
  locals: L;
  status(code: number): Reply<L>;
  json(body: unknown): Reply<L>;
  send(body?: unknown): Reply<L>;
}
export interface Request<B = unknown> {
  body: B;
  params: Record<string, string>;
}
export interface Ctx<B = unknown> {
  body: B;
  json(body: unknown): Ctx<B>;
}
export type Handler<B = unknown, L = Record<string, unknown>> = (req: Request<B>, res: Reply<L>) => void | Promise<void>;
export interface App {
  post<B, L>(path: string, handler: Handler<B, L>): App;
  put<B>(path: string, handler: (c: Ctx<B>) => void): App;
}
declare function make(): App;
export default make;
export declare const reply: Reply;
export declare const ctx: Ctx;
